import type { HTMLAttributes } from "react";
import { cn } from "@/lib/utils";
const tones = { neutral: "bg-muted text-muted-foreground", success: "bg-emerald-50 text-emerald-700", warning: "bg-amber-50 text-amber-800", danger: "bg-rose-50 text-rose-700", info: "bg-blue-50 text-blue-700" };
export function Badge({ tone = "neutral", className, ...props }: HTMLAttributes<HTMLSpanElement> & { tone?: keyof typeof tones }) { return <span className={cn("inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium", tones[tone], className)} {...props} />; }
