import { Badge } from "@/components/ui/badge";
import type { Status } from "@/types/domain";
const tone: Record<Status, "success" | "warning" | "danger" | "info" | "neutral"> = { "on-track": "success", "at-risk": "warning", blocked: "danger", complete: "info", pending: "neutral" };
export function StatusBadge({ status }: { status: Status }) { return <Badge tone={tone[status]}>{status.replace("-", " ")}</Badge>; }
